from AlgorithmImports import *
from datetime import datetime, timedelta, time
from collections import defaultdict


class SpyCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe.Strikes(-100, 100)
                              .Expiration(timedelta(0), timedelta(days=365))
        )
        self.option_symbol = option.Symbol

        self.fast_period = 5
        self.slow_period = 20
        self.closes = []

        self.minute_bars = {}
        self.current_chain = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_contract = None
        self.entry_price = None

        self.no_replacement_today = False
        self.last_processed_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        if self.last_processed_date != current_date:
            self.last_processed_date = current_date
            self.no_replacement_today = False

        self.current_chain = slice.OptionChains.get(self.option_symbol)

        self._handle_unexpected_spy_position()
        self._handle_expiration_processing()

        if self.held_contract is not None:
            self._evaluate_option_exit(slice)

        bar = slice.Bars.get(self.spy)
        if bar is not None:
            self._process_minute_bar(bar)

    def _process_minute_bar(self, bar: TradeBar):
        end_time = bar.EndTime
        local_time = end_time.time()

        # Regular-session minute bars only.
        if local_time < time(9, 31) or local_time > time(16, 0):
            return

        minute_of_day = end_time.hour * 60 + end_time.minute
        bucket_end_minute = ((minute_of_day + 4) // 5) * 5
        bucket_end = end_time.replace(
            hour=bucket_end_minute // 60,
            minute=bucket_end_minute % 60,
            second=0,
            microsecond=0
        )

        if bucket_end.time() < time(9, 35) or bucket_end.time() > time(16, 0):
            return

        bucket = self.minute_bars.setdefault(bucket_end, {})
        bucket[end_time] = bar

        if end_time.time() != bucket_end.time():
            return

        expected_times = [
            bucket_end - timedelta(minutes=i) for i in range(4, -1, -1)
        ]

        # Missing minutes invalidate the five-minute bar.
        if any(timestamp not in bucket for timestamp in expected_times):
            self.minute_bars.pop(bucket_end, None)
            return

        five_minute_close = bucket[end_time].Close
        self.minute_bars.pop(bucket_end, None)

        previous_fast = None
        previous_slow = None

        if len(self.closes) >= self.slow_period:
            previous_fast = sum(self.closes[-self.fast_period:]) / self.fast_period
            previous_slow = sum(self.closes[-self.slow_period:]) / self.slow_period

        self.closes.append(five_minute_close)

        if len(self.closes) < self.slow_period:
            return

        current_fast = sum(self.closes[-self.fast_period:]) / self.fast_period
        current_slow = sum(self.closes[-self.slow_period:]) / self.slow_period

        crossover = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        if not crossover:
            return

        if not (time(9, 45) <= bucket_end.time() <= time(14, 30)):
            return

        self._try_enter_option()

    def _try_enter_option(self):
        if self.no_replacement_today:
            return

        if self.held_contract is not None:
            return

        if self.entry_ticket is not None and self.entry_ticket.Status in (
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ):
            return

        if self.current_chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        current_spy_price = self.Securities[self.spy].Price
        if current_spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        current_date = self.Time.date()
        min_expiry = current_date + timedelta(days=7)

        contracts = [
            contract for contract in self.current_chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= min_expiry
            and contract.Strike >= 1.01 * current_spy_price
        ]

        if not contracts:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in contracts)
        contracts = [
            contract for contract in contracts
            if contract.Expiry.date() == nearest_expiry
        ]

        selected = min(
            contracts,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Entry submitted: {selected.Symbol}; "
            f"expiry={selected.Expiry.date()}, strike={selected.Strike}"
        )

    def _evaluate_option_exit(self, slice: Slice):
        if self.held_contract is None or self.entry_price is None:
            return

        contract = None
        if self.current_chain is not None:
            for candidate in self.current_chain:
                if candidate.Symbol == self.held_contract:
                    contract = candidate
                    break

        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid > 0 and ask > 0:
            midpoint = (bid + ask) / 2.0
            if midpoint >= 1.5 * self.entry_price:
                self._submit_exit("50% profit target")

    def _handle_expiration_processing(self):
        if self.held_contract is None:
            return

        expiry_date = self.Securities[self.held_contract].Symbol.ID.Date.date()

        if self.Time.date() >= expiry_date:
            self.no_replacement_today = True
            self._submit_exit("expiration processing")
            return

        if (
            self.Time.date() == expiry_date - timedelta(days=1)
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("pre-expiration time stop")

    def _submit_exit(self, reason):
        if self.exit_ticket is not None and self.exit_ticket.Status in (
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ):
            return

        if self.held_contract is None:
            return

        if self.entry_ticket is not None and self.entry_ticket.Status in (
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ):
            return

        quantity = -self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None:
            self.Transactions.CancelOrder(self.exit_ticket.OrderId)

        self.exit_ticket = self.MarketOrder(
            self.held_contract,
            quantity,
            tag=reason
        )
        self.Debug(f"Exit submitted: {reason}")

    def _handle_unexpected_spy_position(self):
        holding = self.Portfolio[self.spy]
        if holding.Invested:
            self.Debug("Unexpected SPY exercise or assignment; liquidating SPY.")
            self.Liquidate(self.spy, "Unexpected exercise or assignment")
            self.no_replacement_today = True

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_contract = self.entry_ticket.Symbol
                self.entry_price = order_event.AverageFillPrice
                self.Debug(
                    f"Entry filled: {self.held_contract}; "
                    f"price={self.entry_price}"
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {self.held_contract}")
                self.held_contract = None
                self.entry_price = None
                self.exit_ticket = None
                self.entry_ticket = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

from AlgorithmImports import *
from datetime import datetime, timedelta, time
from collections import deque


class SpyFiveMinuteCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda u: u.IncludeWeeklys()
                      .Strikes(-100, 100)
                      .Expiration(0, 730)
        )
        self.option_symbol = option.Symbol

        self.fast_window = deque(maxlen=5)
        self.slow_window = deque(maxlen=20)

        self.current_bucket_end = None
        self.bucket_bars = []

        self.entry_ticket = None
        self.entry_price = None
        self.held_option = None
        self.exit_ticket = None
        self.time_stop_submitted = False
        self.blocked_entry_date = None
        self.last_exercise_notice = None

    def OnData(self, slice: Slice):
        now = self.Time
        today = now.date()

        self._handle_unexpected_spy_position()

        if self.held_option is not None and self.Portfolio[self.held_option].Invested:
            self._evaluate_open_position(slice)
        else:
            self.held_option = None
            self.entry_price = None
            self.time_stop_submitted = False

        if self.spy not in slice.Bars:
            return

        self._process_minute_bar(slice.Bars[self.spy], slice)

    def _process_minute_bar(self, minute_bar: TradeBar, slice: Slice):
        local_end = minute_bar.EndTime.astimezone(self.TimeZone)
        session_start = datetime.combine(
            local_end.date(), time(9, 30), local_end.tzinfo
        )
        session_end = datetime.combine(
            local_end.date(), time(16, 0), local_end.tzinfo
        )

        if local_end <= session_start or local_end > session_end:
            return

        elapsed_minutes = int((local_end - session_start).total_seconds() // 60)
        bucket_number = (elapsed_minutes + 4) // 5
        bucket_end = session_start + timedelta(minutes=bucket_number * 5)

        if self.current_bucket_end is None:
            self.current_bucket_end = bucket_end
            self.bucket_bars = []

        if bucket_end != self.current_bucket_end:
            self.current_bucket_end = bucket_end
            self.bucket_bars = []

        self.bucket_bars.append(minute_bar)

        if len(self.bucket_bars) != 5:
            return

        expected_times = [
            self.current_bucket_end - timedelta(minutes=i)
            for i in range(5, 0, -1)
        ]
        actual_times = [
            bar.EndTime.astimezone(self.TimeZone)
            for bar in self.bucket_bars
        ]

        if actual_times != expected_times:
            self.bucket_bars = []
            return

        close = self.bucket_bars[-1].Close
        self.bucket_bars = []

        previous_fast = (
            sum(self.fast_window) / len(self.fast_window)
            if len(self.fast_window) == 5 else None
        )
        previous_slow = (
            sum(self.slow_window) / len(self.slow_window)
            if len(self.slow_window) == 20 else None
        )

        self.fast_window.append(close)
        self.slow_window.append(close)

        if len(self.fast_window) < 5 or len(self.slow_window) < 20:
            return

        current_fast = sum(self.fast_window) / 5
        current_slow = sum(self.slow_window) / 20

        bullish_cross = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        bar_end_time = self.current_bucket_end.time()
        eligible_time = time(9, 45) <= bar_end_time <= time(14, 30)

        if bullish_cross and eligible_time:
            self._try_enter(slice, close)

    def _try_enter(self, slice: Slice, spy_price: float):
        today = self.Time.date()

        if self.blocked_entry_date == today:
            return

        if self.entry_ticket is not None and not self.entry_ticket.Status.IsClosed():
            return

        if self.held_option is not None and self.Portfolio[self.held_option].Invested:
            return

        chains = list(slice.OptionChains)
        if not chains:
            self.Debug(f"{self.Time}: skipped entry; no option chain")
            return

        minimum_expiry = today + timedelta(days=7)
        contracts = []

        for chain in chains:
            for contract in chain:
                if contract.Right != OptionRight.Call:
                    continue

                expiry_date = contract.Expiry.date()
                if expiry_date >= minimum_expiry:
                    contracts.append(contract)

        if not contracts:
            self.Debug(f"{self.Time}: skipped entry; no qualifying expiration")
            return

        nearest_expiry = min(c.Expiry.date() for c in contracts)
        strike_floor = 1.01 * spy_price

        candidates = [
            c for c in contracts
            if c.Expiry.date() == nearest_expiry
            and c.Strike >= strike_floor
        ]

        if not candidates:
            self.Debug(f"{self.Time}: skipped entry; no qualifying call strike")
            return

        selected = sorted(
            candidates,
            key=lambda c: (c.Strike, str(c.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.held_option = selected.Symbol
        self.time_stop_submitted = False

        self.Debug(
            f"{self.Time}: call entry submitted for {selected.Symbol}"
        )

    def _evaluate_open_position(self, slice: Slice):
        symbol = self.held_option
        holding = self.Portfolio[symbol]

        if not holding.Invested:
            return

        expiry_date = symbol.ID.Date.date()
        today = self.Time.date()
        now_time = self.Time.time()

        if today >= expiry_date:
            self.blocked_entry_date = today
            if self.exit_ticket is None or self.exit_ticket.Status.IsClosed():
                self.exit_ticket = self.MarketOrder(
                    symbol, -holding.Quantity
                )
                self.Debug(
                    f"{self.Time}: expiration protection exit submitted"
                )
            return

        if (
            today == expiry_date - timedelta(days=1)
            and now_time >= time(15, 45)
            and not self.time_stop_submitted
        ):
            self.blocked_entry_date = today
            self.time_stop_submitted = True

            if self.exit_ticket is not None and not self.exit_ticket.Status.IsClosed():
                self.exit_ticket.Cancel("Time stop superseded prior exit")

            self.exit_ticket = self.MarketOrder(symbol, -holding.Quantity)
            self.Debug(f"{self.Time}: expiration time-stop submitted")
            return

        if symbol not in slice.OptionChains and symbol not in slice.Bars:
            return

        bid = None
        ask = None

        for chain in slice.OptionChains:
            contract = chain.Contracts.get(symbol)
            if contract is not None:
                bid = contract.BidPrice
                ask = contract.AskPrice
                break

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        if self.entry_price is None:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint < 1.50 * self.entry_price:
            return

        if self.exit_ticket is not None and not self.exit_ticket.Status.IsClosed():
            self.exit_ticket.Cancel("Profit target reached")

        self.exit_ticket = self.MarketOrder(symbol, -holding.Quantity)
        self.Debug(f"{self.Time}: 50% profit-target exit submitted")

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status != OrderStatus.Filled:
            return

        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.FillQuantity > 0:
                self.entry_price = order_event.FillPrice
                self.held_option = order_event.Symbol
                self.Debug(
                    f"{self.Time}: call entry filled at {order_event.FillPrice}"
                )

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.FillQuantity < 0:
                self.Debug(
                    f"{self.Time}: call exit filled at {order_event.FillPrice}"
                )

        if getattr(order_event, "IsAssignment", False):
            self.Debug(
                f"{self.Time}: unexpected exercise or assignment received"
            )
            if self.spy in self.Portfolio and self.Portfolio[self.spy].Invested:
                self.MarketOrder(
                    self.spy, -self.Portfolio[self.spy].Quantity
                )

    def _handle_unexpected_spy_position(self):
        if self.spy not in self.Portfolio:
            return

        holding = self.Portfolio[self.spy]
        if not holding.Invested:
            return

        if self.last_exercise_notice != self.Time.date():
            self.Debug(
                f"{self.Time}: unexpected SPY equity position; liquidating"
            )
            self.last_exercise_notice = self.Time.date()

        self.MarketOrder(self.spy, -holding.Quantity)
        self.blocked_entry_date = self.Time.date()

from AlgorithmImports import *
from datetime import timedelta, time


class SpyCallCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetTimeZone("America/New_York")
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda u: u.IncludeWeeklys()
                       .Strikes(-200, 200)
                       .Expiration(0, 365)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(
            self.spy.Symbol,
            self.consolidator
        )

        self.pending_signal = False
        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.expiration_shutdown = False

    def OnFiveMinuteBar(self, sender, bar):
        end_time = bar.EndTime

        if end_time.weekday() >= 5:
            return

        if end_time.time() < time(9, 30) or end_time.time() > time(16, 0):
            return

        previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(end_time, bar.Close)
        self.slow.Update(end_time, bar.Close)

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        if previous_fast is None or previous_slow is None:
            return

        bullish_cross = (
            previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        if (
            bullish_cross
            and time(9, 45) <= end_time.time() <= time(14, 30)
        ):
            self.pending_signal = True

    def OnData(self, slice):
        now = self.Time
        today = now.date()

        # The strategy never intentionally owns SPY equity.
        if self.Portfolio[self.spy.Symbol].Quantity != 0:
            self.Debug("Unexpected exercise or assignment; liquidating SPY equity")
            self.Liquidate(self.spy.Symbol, "Unexpected assignment")

        if self.held_symbol is not None:
            if self._expiration_processing(today):
                self._liquidate_option("Expiration protection")

            elif self._pre_expiration_time_stop(now):
                self._liquidate_option("Pre-expiration time stop")

            else:
                chain = slice.OptionChains.get(self.option.Symbol)

                if chain is not None and self.entry_price is not None:
                    contract = next(
                        (c for c in chain if c.Symbol == self.held_symbol),
                        None
                    )

                    if (
                        contract is not None
                        and contract.BidPrice > 0
                        and contract.AskPrice > 0
                    ):
                        midpoint = (
                            contract.BidPrice + contract.AskPrice
                        ) / 2.0

                        if midpoint >= 1.5 * self.entry_price:
                            self._liquidate_option("50% profit target")

        if (
            self.pending_signal
            and self.held_symbol is None
            and self.entry_ticket is None
            and not self.expiration_shutdown
        ):
            self.pending_signal = False
            self._try_entry(slice)

    def _try_entry(self, slice):
        chain = slice.OptionChains.get(self.option.Symbol)

        if chain is None:
            self.Debug("Skipped entry: no option chain")
            return

        today = self.Time.date()
        minimum_expiry = today + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no eligible expiration")
            return

        selected_expiry = expirations[0]
        threshold = self.Securities[self.spy.Symbol].Price * 1.01

        candidates = [
            contract
            for contract in chain
            if (
                contract.Expiry.date() == selected_expiry
                and contract.Right == OptionRight.Call
                and contract.Strike >= threshold
            )
        ]

        if not candidates:
            self.Debug("Skipped entry: no eligible call contract")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover"
        )

        self.Debug("Entry submitted: " + str(selected.Symbol))

    def OnOrderEvent(self, order_event):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.held_symbol = order_event.Symbol
            self.entry_price = order_event.FillPrice
            self.entry_ticket = None

            self.Debug(
                "Entry filled: {} at {}".format(
                    self.held_symbol,
                    self.entry_price
                )
            )

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug("Exit filled: " + str(order_event.Symbol))
            self.exit_ticket = None
            self.held_symbol = None
            self.entry_price = None

    def OnAssignmentOrder(self, assignment_event):
        self.Debug("Unexpected option exercise or assignment received")
        self.expiration_shutdown = True

        if self.Portfolio[self.spy.Symbol].Quantity != 0:
            self.Liquidate(self.spy.Symbol, "Assignment handling")

    def _liquidate_option(self, reason):
        if self.held_symbol is None or self.exit_ticket is not None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity

        if quantity == 0:
            return

        if self.entry_ticket is not None:
            self.Transactions.CancelOrder(self.entry_ticket.OrderId)
            self.entry_ticket = None

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )

        self.Debug("Exit submitted: " + reason)

    def _expiration_processing(self, current_date):
        if self.held_symbol is None:
            return False

        expiry = self.Securities[
            self.held_symbol
        ].Symbol.ID.Date.date()

        if current_date >= expiry:
            self.expiration_shutdown = True
            return True

        return False

    def _pre_expiration_time_stop(self, current_time):
        if current_time.time() < time(15, 45):
            return False

        expiry = self.Securities[
            self.held_symbol
        ].Symbol.ID.Date.date()

        next_trading_day = current_time.date() + timedelta(days=1)

        while not self.Securities[
            self.spy.Symbol
        ].Exchange.Hours.IsDateOpen(next_trading_day):
            next_trading_day += timedelta(days=1)

        return next_trading_day == expiry
